const update = $json;
const callbackQuery = update.callback_query || null;
const message = update.message || callbackQuery?.message || {};
const from = update.message?.from || callbackQuery?.from || {};
const text = typeof update.message?.text === 'string' ? update.message.text.trim() : '';
const callbackData = callbackQuery?.data || '';

return [{
  json: {
    telegram_user_id: from.id,
    chat_id: message.chat?.id,
    username: from.username || null,
    first_name: from.first_name || null,
    text,
    callback_data: callbackData,
    callback_query_id: callbackQuery?.id || null,
    is_callback: Boolean(callbackQuery)
  }
}];

const update = $('Normalize Update').item.json;
const user = $input.first().json || {};
const action = update.callback_data || update.text || '';

return [{
  json: {
    user_id: user.id,
    telegram_user_id: update.telegram_user_id,
    chat_id: update.chat_id,
    username: update.username || user.username || null,
    first_name: update.first_name || user.first_name || null,
    text: update.text || '',
    action,
    callback_data: update.callback_data || '',
    callback_query_id: update.callback_query_id,
    is_callback: update.is_callback,
    selected_agent_id: user.selected_agent_id || null,
    state: user.state || null
  }
}];

