const rows = $input.all().map(item => item.json).filter(row => row.id);
if (!rows.length) {
  return [{ json: { text: 'You do not have any available agents yet.', reply_markup: { inline_keyboard: [[{ text: 'Menu', callback_data: 'menu' }]] } } }];
}
return [{
  json: {
    text: 'Your available agents:',
    reply_markup: { inline_keyboard: rows.map(agent => ([{ text: agent.display_name, callback_data: 'agent:select:' + agent.id }])).concat([[{ text: 'Menu', callback_data: 'menu' }]]) }
  }
}];

const ctx = $json;
const raw = ctx.callback_data || ctx.action || '';
const agentId = Number(raw.split(':')[2]);
return [{ json: { ...ctx, agent_id_from_callback: Number.isFinite(agentId) ? agentId : 0 } }];

